// Minimal 1-bit bitmap font renderer for the Dot Matrix fonts.
// Fonts are generated by esp32/tools/fontconv.py; drawing matches the
// original Pi app's Pillow rendering pixel for pixel.
#pragma once
#include <Arduino.h>
#include <U8g2lib.h>

struct DMGlyph {
  uint16_t offset;   // into the font's bitmap array
  uint8_t w, h;      // bitmap size (rows are byte-aligned, MSB first)
  int8_t xo, yo;     // offset from the text origin (top-left of the line)
  uint8_t adv;       // advance width
  uint8_t boxRight;  // Pillow getbbox() right edge for this glyph alone
};

struct DMFont {
  const uint8_t *bitmaps;
  const DMGlyph *glyphs;
  uint8_t first, last;
  uint8_t height;    // line height (ascent + descent)
};

// Width in pixels of text, as Pillow's font.getlength() reports it.
int dmTextWidth(const DMFont &font, const char *text);

// Width as Pillow's font.getbbox(text)[2] reports it; the original app uses
// this to right-align the status column.
int dmBoxWidth(const DMFont &font, const char *text);

// Height as Pillow's font.getbbox(text)[3] reports it (bottom of the ink).
int dmBoxHeight(const DMFont &font, const char *text);

// Draw text with its top-left corner at (x, y). Pixels outside the current
// U8g2 clip window are skipped. Returns the x position after the text.
int dmDrawText(U8G2 &u8g2, const DMFont &font, int x, int y, const char *text);
